    image_patch = ImagePatch(image)
    hot_dog_patches = image_patch.find("hot dog")
    bacon_patches = image_patch.find("bacon")

    if not hot_dog_patches:
        return image_patch  # Return the entire image if no hot dog is found
    if not bacon_patches:
        return hot_dog_patches[0]  # Return the first hot dog if no bacon is found

    # Sort hot dog patches by depth, the closest to the camera first
    hot_dog_patches.sort(key=lambda p: p.compute_depth())

    # Find the first hot dog next to bacon
